// limiter.go
package tokenbucket

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It refills continuously at rate tokens per second up to capacity tokens.
type Limiter struct {
	mu sync.Mutex

	capacity float64
	rate     float64 // tokens per second
	clock    Clock

	tokens float64
	last   time.Time
}

// New returns a limiter with the given capacity, refill rate, and clock.
// If clock is nil, the system clock is used.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || isInvalid(capacity) {
		return nil, errors.New("tokenbucket: capacity must be > 0 and finite")
	}
	if rate <= 0 || isInvalid(rate) {
		return nil, errors.New("tokenbucket: rate must be > 0 and finite")
	}
	if clock == nil {
		clock = realClock{}
	}

	return &Limiter{
		capacity: capacity,
		rate:     rate,
		clock:    clock,
		tokens:   capacity,
		last:     clock.Now(),
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive and no greater than capacity. Requests larger than
// capacity are always denied without consuming tokens.
func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 {
		return false
	}
	if float64(n) > l.capacity {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the currently available tokens after applying refill.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

func isInvalid(v float64) bool {
	return v != v || v > 1.7976931348623157e308 || v < -1.7976931348623157e308
}

var _ = fmt.Sprintf // keep fmt available for future wrapped errors without API churn
