package tokenbucket

import (
	"math"
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{t: t} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	c.t = c.t.Add(d)
	c.mu.Unlock()
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 2, clk, false},
		{"nil clock uses real", 10, 2, nil, false},
		{"zero capacity", 0, 2, clk, true},
		{"negative capacity", -1, 2, clk, true},
		{"nan capacity", math.NaN(), 2, clk, true},
		{"inf capacity", math.Inf(1), 2, clk, true},
		{"zero rate", 10, 0, clk, true},
