// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock returns a Clock backed by time.Now.
func SystemClock() Clock { return systemClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// Tokens are replenished continuously at rate tokens per second up to burst.
// AllowN consumes n tokens if available at the current time.
type Limiter struct {
	mu sync.Mutex

	clock Clock
	rate  float64 // tokens / second
	burst float64

	tokens float64
	last   time.Time
}

// New creates a Limiter with the given sustained rate and maximum burst.
// rate must be positive and finite; burst must be positive and finite.
// The bucket starts full. If clock is nil, SystemClock is used.
func New(rate float64, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || !isFinite(rate) {
		return nil, errors.New("ratelimit: rate must be positive and finite")
	}
	if burst <= 0 || !isFinite(burst) {
		return nil, errors.New("ratelimit: burst must be positive and finite")
	}
	if clock == nil {
		clock = SystemClock()
	}

	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n <= 0 is always allowed and consumes nothing. n must be finite when
// converted to float64; integer values are always finite.
func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 {
		return true
	}
	need := float64(n)
	if !isFinite(need) {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	if need > l.tokens {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the number of tokens currently available.
// It is primarily useful for diagnostics and tests.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func (l *Limiter) refill(now time.Time) {
	if now.Before(l.last) {
		// Ignore non-monotonic clock movement; keep last to avoid granting
		// extra tokens from a backwards jump.
		return
	}

	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.last = now

	if !isFinite(elapsed) {
		l.tokens = l.burst
		return
	}

	l.tokens += elapsed * l.rate
	if l.tokens > l.burst || !isFinite(l.tokens) {
		l.tokens = l.burst
	}
}

func isFinite(v float64) bool {
	return !mathIsNaN(v) && !mathIsInf(v, 0)
}

// Avoid importing math in the public surface while keeping finite checks clear.
func mathIsNaN(v float64) bool { return v != v }
func mathIsInf(v float64, sign int) bool {
	const maxFloat64 = 1.797693134862315708145274237317043567981e+308
	if sign > 0 {
		return v > maxFloat64
	}
	if sign < 0 {
		return v < -maxFloat64
	}
	return v > maxFloat64 || v < -maxFloat64
}

var _ = fmt.Sprintf // keep fmt available for future structured errors without API churn
