// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock returns a Clock backed by time.Now.
func SystemClock() Clock { return systemClock{} }

// Limiter is a concurrency-safe token bucket.
//
// Tokens are replenished continuously at rate tokens per second up to burst.
// AllowN consumes n tokens if available at the current time.
type Limiter struct {
	mu sync.Mutex

	clock Clock
	rate  float64 // tokens / second
	burst float64

	tokens float64
	last   time.Time
}

// New creates a Limiter with the given refill rate and burst capacity.
// rate must be positive and finite; burst must be positive and finite.
// The bucket starts full. If clock is nil, SystemClock is used.
func New(rate float64, burst float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		clock = SystemClock()
	}
	if err := validateRate(rate); err != nil {
		return nil, err
	}
	if err := validateBurst(burst); err != nil {
		return nil, err
	}
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
	}, nil
}

// MustNew is like New but panics on invalid configuration.
func MustNew(rate float64, burst float64, clock Clock) *Limiter {
	l, err := New(rate, burst, clock)
	if err != nil {
		panic(err)
	}
	return l
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive. n greater than burst is never allowed.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	need := float64(n)
	if need > l.burst || l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the number of available tokens at the current time.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// refill updates token state based on elapsed time. Caller must hold mu.
func (l *Limiter) refill(now time.Time) {
	if now.Before(l.last) {
		// Ignore non-monotonic clock movement; keep last to avoid granting
		// extra tokens from a backwards jump.
		return
	}
	elapsed := now.Sub(l.last).Seconds()
	l.last = now
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
}

func validateRate(rate float64) error {
	if rate <= 0 || isInvalidFloat(rate) {
		return errors.New("ratelimit: rate must be positive and finite")
	}
	return nil
}

func validateBurst(burst float64) error {
	if burst <= 0 || isInvalidFloat(burst) {
		return errors.New("ratelimit: burst must be positive and finite")
	}
	return nil
}

func isInvalidFloat(v float64) bool {
	return v != v || v > 1.7976931348623157e308 || v < -1.7976931348623157e308
}

// Compile-time assertion for a useful error string in future wrapping.
var _ = fmt.Sprintf
