					clk.Advance(s.advance)
				}
				if s.setBack != 0 {
					clk.Set(clk.Now().Add(-s.setBack))
				}
				if s.allowN != 0 || s.want == false {
					got := l.AllowN(s.allowN)
					if got != s.want {
						t.Fatalf("step %d: AllowN(%d) = %v, want %v; tokens=%v",
							i, s.allowN, got, s.want, l.Tokens())
					}
				}
			}
		})
	}
}

type step struct {
	advance time.Duration
	setBack time.Duration
	allowN  int
	want    bool
}

func TestAllowAndTokens(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0).UTC())
	l := MustNew(4, 2, clk)

	if got := l.Tokens(); got != 2 {
		t.Fatalf("Tokens() = %v, want 2", got)
