// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock returns a Clock backed by time.Now.
func SystemClock() Clock { return systemClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// Tokens are replenished continuously at rate tokens per second up to burst.
// AllowN consumes n tokens if available at the current time.
type Limiter struct {
	mu sync.Mutex

	clock Clock
	rate  float64 // tokens / second
	burst float64

	tokens float64
	last   time.Time
}

// New creates a Limiter with burst capacity and sustained rate tokens/second.
// rate and burst must be finite and positive. clock may be nil to use SystemClock.
func New(rate float64, burst int64, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, errors.New("ratelimit: rate and burst must be positive")
	}
	if isNonFinite(rate) {
		return nil, errors.New("ratelimit: rate must be finite")
	}
	if clock == nil {
		clock = SystemClock()
	}

	now := clock.Now()
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   now,
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive and no greater than burst. It never blocks.
func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 || float64(n) > l.burst {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the currently available tokens after applying elapsed refill.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// refill must be called with l.mu held.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		// Keep last monotonic for non-monotonic or rewound clocks.
		if now.Before(l.last) {
			l.last = now
		}
		return
	}
	l.last = now
	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
}

func isNonFinite(f float64) bool {
	return f != f || f > 1.7976931348623157e308 || f < -1.7976931348623157e308
}

// Compile-time guard against accidental interface changes.
var _ = fmt.Sprintf
