// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock returns a Clock backed by time.Now.
func SystemClock() Clock { return systemClock{} }

// Limiter is a concurrency-safe token bucket.
//
// Tokens are replenished continuously at rate tokens per second up to burst.
// AllowN consumes n tokens if they are available at the current time.
type Limiter struct {
	mu sync.Mutex

	clock Clock
	rate  float64 // tokens / second
	burst float64

	tokens float64
	last   time.Time
}

// New creates a Limiter with the given sustained rate and maximum burst.
// rate must be positive and finite; burst must be positive and finite.
func New(rate float64, burst float64) (*Limiter, error) {
	return NewWithClock(rate, burst, SystemClock())
}

// NewWithClock is New with an injectable clock.
func NewWithClock(rate float64, burst float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 || !isFinite(rate) {
		return nil, fmt.Errorf("ratelimit: rate must be positive and finite, got %v", rate)
	}
	if burst <= 0 || !isFinite(burst) {
		return nil, fmt.Errorf("ratelimit: burst must be positive and finite, got %v", burst)
	}

	now := clock.Now()
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   now,
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available and consumes them if so.
// n <= 0 is always allowed without consuming tokens. n must be finite-safe
// for float conversion; extremely large integer values are rejected by the
// availability check rather than panicking.
func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 {
		return true
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	need := float64(n)
	if !isFinite(need) || need > l.tokens {
		return false
	}

	l.tokens -= need
	return true
}

// Tokens returns the number of tokens currently available. It is primarily
// useful for diagnostics and tests.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func (l *Limiter) refill(now time.Time) {
	if now.Before(l.last) {
		// Ignore non-monotonic clock movement; keep last to avoid granting
		// extra tokens from a backwards jump.
		return
	}

	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}

	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}

func isFinite(v float64) bool {
	return !(v != v || v > 1.7976931348623157e308 || v < -1.7976931348623157e308)
}
